            s0 = solutions[0]
            s1 = solutions[1]
            k = gcd(s0[0] - s1[0], s1[1] - s0[1])**2
            h = gcd(s0[0] + s1[0], s1[1] + s0[1])**2
            m = gcd(s0[0] + s1[0], s1[1] - s0[1])**2
            lev = gcd(s0[0] - s1[0], s1[1] + s0[1])**2
